            if e.code>=500:
                print(f'token server error {e.code}; retrying in 2s',file=sys.stderr); time.sleep(2); continue
            raise RuntimeError(f'token request failed: HTTP {e.code} {body}')
        except (urllib.error.URLError,TimeoutError) as e:
            print(f'token request error {e}; retrying in 2s',file=sys.stderr); time.sleep(2)

def retry_delay(headers, body):
    v=headers.get('Retry-After')
    if v:
        try: return max(0.0,float(v))
        except ValueError:
            try: return max(0.0,email.utils.parsedate_to_datetime(v).timestamp()-time.time())
            except Exception: pass
    try:
        j=json.loads(body)
        for k in ('retry_after','wait','wait_seconds','retry_in'):
            if k in j: return max(0.0,float(j[k]))
