        if m: return float(m.group(1))
    except Exception: pass
    m=re.search(r'([0-9]+(?:\\.[0-9]+)?)\\s*seconds?',body,re.I)
    if m: return float(m.group(1))
    raise RuntimeError(f'429 response did not specify wait: {body}')

