    while True:
        if token is None: token=[REDACTED_SECRET]
        req=urllib.request.Request(BASE+path, method=method, headers={'Authorization':'Bearer '+token})
        try:
            with urllib.request.urlopen(req,timeout=30) as r:
                return json.loads(r.read())
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors='replace')
            if e.code==401:
                token=None; print('token expired; refreshing',file=sys.stderr); continue
            if e.code==429:
                delay=retry_delay(e.headers,body)
                print(f'{path} rate limited; waiting {delay}s',file=sys.stderr); time.sleep(delay); continue
            if e.code>=500:
                print(f'{path} server error {e.code}; retrying in 2s',file=sys.stderr); time.sleep(2); continue
            raise RuntimeError(f'{path}: HTTP {e.code} {body}')
        except (urllib.error.URLError,TimeoutError) as e:
            print(f'{path} request error {e}; retrying in 2s',file=sys.stderr); time.sleep(2)

all_orders=[]
page=1
pages=None
while pages is None or page<=pages:
    data=request_json(f'/orders?page={page}')
    if data.get('page')"'!=page: raise RuntimeError(f'"'unexpected page payload: requested {page}, got {data.get(\"page\")}')
    if pages is None:
        pages=data['total_pages']; print(f'total pages: {pages}',file=sys.stderr)
    all_orders.extend(data['items'])
    page+=1

seen=set(); distinct=[]; duplicates=0
for o in all_orders:
    oid=o['id']
    if oid in seen: duplicates+=1
    else: seen.add(oid); distinct.append(o)

start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
qual=[]
for o in distinct:
    if o['status']"'!='"'shipped': continue
    dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00'))
    if dt.tzinfo is None: raise RuntimeError(f'naive placed_at: {o}')
    dt=dt.astimezone(datetime.timezone.utc)
    if start<=dt<end: qual.append(o)

customers={}
for o in qual:
    cid=o['customer_id']
    if cid not in customers:
        c=request_json('/customers/'+urllib.parse.quote(str(cid),safe=''))
        if c['id']"'!=cid and str(c['"'id'])"'!=str(cid): raise RuntimeError(f'"'customer id mismatch for {cid}: {c}')
        customers[cid]=c

regions={x:0 for x in ('north','south','east','west')}
for o in qual:
    c=customers[o['customer_id']]
    amount=o['amount_cents']*(100-c['discount_pct'])
    # Integer half-up rounding: amount*(100-discount)/100
    discounted=(amount+50)//100
    regions[c['region']]+=discounted
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps({'raw_listing_count':len(all_orders),'distinct_count':len(distinct),'duplicates_skipped':duplicates,'qualifying_orders':len(qual),'customers_cached':len(customers),'result':result},indent=2))
